  const findStaff=q=>{if(!tables().includes('Employees'))return[];const qt=tok(q),es=D().Employees,byId=es.find(e=>qt.includes(String(e.StaffID).toLowerCase()));if(byId)return[byId];let best=[],sc=0;
    for(const e of es){const nt=tok(e.FullName);const m=nt.filter(t=>qt.some(x=>x===t||(x.length>3&&t.length>3&&lev(x,t)<=1))).length;if(m>sc){sc=m;best=[e]}else if(m===sc&&m>0)best.push(e)}return sc>=1?best:[]};
