/* ================= intent routing and plan validation ================= */
const SYN={Employees:/employee|staff|personnel|scientist|people|team/i,Methods:/method|sop|procedure/i,Training:/training/i,Authorization:/authori[sz]/i,Instruments:/instrument/i,InstrumentInventory:/inventory/i,Evaluation:/evaluation|competen/i,IQAS:/iqas/i,EQAS:/eqas/i,Gap:/\bgaps?\b/i,Plan:/plan/i,Literature:/literature review/i,JobDesc:/job desc/i,Flags:/flags?/i};
