  const research=/\b(literature|papers?|studies|study|pubmed|publications?|journal|doi|peer.?reviewed|state of the art|scientific evidence|research)\b/i.test(q)||/أبحاث|دراسة|دراسات|منشور/.test(q);
  const authFor=/authori[sz]ed\s+(?:for|on|to run|to perform)|who (?:can|is allowed to) (?:run|perform|do)|certified (?:for|on)/i.test(q);
  const methodsOfP=/\bmethods?\s+(?:of|for|does|is|are)\b|authori[sz]ed methods|what (?:methods|can)\b/i.test(q);
  const trainOf=/training(?:s)?\s+(?:of|for|done|record|history)|(?:trained|training)\b.*\b(?:last|in|during)\b/i.test(q);
  const countQ=/\b(how many|count|number of|total)\b/i.test(q),listQ=/\b(list|show|display|give me|which|who)\b/i.test(q);
  const dbWords=/\b(employees?|staff|personnel|training|authori[sz]\w*|methods?|instruments?|evaluations?|competen\w+|gaps?|iqas|eqas|plans?|job descriptions?|inventory|documents?|sops?|flags?)\b/i.test(q);
  const intentDb=authFor||methodsOfP||trainOf||(dbWords&&(countQ||listQ||/\b(my|our|the laboratory|the lab)\b/i.test(q)));
  if(authFor){tools.push({name:'authorized_for',args:{q}});why.push('question asks who is authorised for a method')}
  else if(trainOf){tools.push({name:'training_of',args:{q}});why.push('question asks about training records')}
  else if(methodsOfP&&!authFor){tools.push({name:'methods_of',args:{q}});why.push('question asks about a person\'s methods')}
  if(countQ){const t=Object.keys(SYN).find(k=>SYN[k].test(q));if(t){tools.push({name:'db_query',args:{table:t,limit:5,count:true}});why.push('count question about '+t)}}
