  b.querySelectorAll('[data-t]').forEach(x=>x.onclick=()=>{DQ.table=x.dataset.t;DQ.cols=[];DQ.order='';DQ.f.forEach(f=>f.col='');DRES=null;dataTab(b,S)});
  b.querySelector('#dq-run').onclick=()=>{sync();DRES=rd.query({table:DQ.table,columns:DQ.cols,where:DQ.f.filter(f=>f.col),orderBy:DQ.order,dir:DQ.dir,limit:DQ.limit});dataTab(b,S)};
  b.querySelector('#dq-csv').onclick=()=>{if(!DRES||!DRES.rows)return;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csvOf(DRES)],{type:'text/csv'}));a.download='EDCL-'+DRES.table+'.csv';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},2000)};
  const ds=()=>{const q=b.querySelector('#ds-q').value,r=rd.search(q,{limit:60}),by={};for(const x of r)(by[x.table]=by[x.table]||[]).push(x.row);DSRCH={q,rows:r,by};dataTab(b,S)};b.querySelector('#ds-go').onclick=ds;b.querySelector('#ds-q').onkeydown=e=>{if(e.key==='Enter')ds()};
