/* ---- Research (public scientific sources through the privacy gateway) ---- */
let RRES=null;
const researchTab=async(b,S)=>{const s=await gwStatus();
  if(!gw()){b.innerHTML=`<div class="edai-warn">Web and scientific research need the <b>privacy gateway</b> (integration patch 2 of the AI Assistant package). It is not installed on this PC, so the assistant works in local mode. See the installation guide.</div>`;return}
  b.innerHTML=`<div class="edai-note">Searches public scientific sources (PubMed, Europe PMC, Crossref) through the privacy gateway. Only the search words leave this PC; the gateway blocks any query that contains names, staff IDs, internal codes, contact data or other confidential-looking text. Approved sites: ${E(((s&&s.hosts)||[]).join(', '))}.</div><div class="bar"><input id="rs-q" placeholder="e.g. 19-norandrosterone IRMS urine confirmation" style="flex:1;min-width:240px" value="${E((RRES||{}).q||'')}"><select id="rs-s"><option value="pubmed">PubMed</option><option value="europepmc">Europe PMC</option><option value="crossref">Crossref</option></select><button class="btn" id="rs-go">Search</button></div><div id="rs-out"></div>`;
  const out=b.querySelector('#rs-out');const show=()=>{if(!RRES)return;out.innerHTML=(RRES.error?`<div class="edai-warn">${E(RRES.error)}</div>`:RRES.results.length?`<div class="bar"><button class="btn s" id="rs-sum">✨ Summarise these results</button></div>`+resHtml(RRES.results):'<div class="edai-note">No results.</div>')+(RRES.sum?`<div class="edai-m a" style="max-width:100%;margin-top:10px">${E(RRES.sum.content)}<div class="edai-note">${E(RRES.sum.priv)}</div></div>`:'');out.querySelectorAll('[data-edurl]').forEach(a=>a.onclick=()=>openUrl(a.dataset.edurl));const sm=out.querySelector('#rs-sum');if(sm)sm.onclick=async()=>{sm.disabled=true;sm.textContent='Summarising…';const ev=[{id:'R1',kind:'research',cls:'public',title:'Scientific literature',results:RRES.results,hits:RRES.results.map(x=>({doc:{name:x.source+': '+x.title,version:x.year,type:'Literature'},chunk:{page:0,text:(x.abstract||x.title)+' ['+(x.journal||'')+' '+(x.year||'')+']'}})),text:RRES.results.map(x=>`(${x.authors}; ${x.journal} ${x.year}) ${x.title}. ${x.abstract||''}`).join('\n')}];try{RRES.sum=await composeAnswer('Summarise the main findings of these studies for a doping-control laboratory scientist and list the key analytical points: '+RRES.q,S,{ev,steps:[],ctx:{sent:[]}},[])}catch(e){RRES.sum={content:'Error: '+e.message,priv:''}}show()}};show();
  const go=async()=>{const q=b.querySelector('#rs-q').value.trim();if(!q)return;out.innerHTML='<div class="edai-note">Searching…</div>';const block=buildBlocklist(()=>hostG('D')),sc=screenOut(q,block);if(!sc.ok){RRES={q,error:'Blocked: the query contains confidential-looking data ('+sc.hits.join(', ')+'). Use only public scientific words.'};return show()}
    try{const r=await gw().research({source:b.querySelector('#rs-s').value,query:q,limit:8,user:curUser()});RRES={q,results:r.results}}catch(e){RRES={q,error:e.message}}show()};
  b.querySelector('#rs-go').onclick=go;b.querySelector('#rs-q').onkeydown=e=>{if(e.key==='Enter')go()}};

const searchTab=(b,S)=>{b.innerHTML=statusLine(S)+`<div class="bar"><input id="edai-sq" placeholder="Search words, document numbers (e.g. TD2027NA), requirements…" style="flex:1;min-width:240px"><select id="edai-st"><option value="">All document types</option>${TYPES.map(t=>`<option>${t}</option>`).join('')}</select><button class="btn" id="edai-sg">Search</button></div><div id="edai-res"></div>`;
  const run=()=>{const q=b.querySelector('#edai-sq').value,t=b.querySelector('#edai-st').value,h=IDX.search(q,{limit:25,types:t?[t]:null});
    const oh=(ONLINE&&q.trim()&&!t)?ONLINE.search(q,{limit:8,minHit:.5}):[];const onl=oh.length?`<h3 style="margin:14px 0 4px">🌐 WADA website (synced by WADA Updates)</h3>`+oh.map(x=>`<div class="edai-r"><span class="edai-tag">🌐 WADA website</span><b>${E(x.chunk.item.title)}</b> · ${x.chunk.item.published?'published '+E(x.chunk.item.published)+' · ':''}${E(x.chunk.item.last_status||'')} · <a data-edopen="${E(x.chunk.item.id)}" style="cursor:pointer">Open on WADA ↗</a></div>`).join(''):'';
      b.querySelector('#edai-res').innerHTML=(q.trim()?(h.length?h.map(x=>`<div class="edai-r"><span class="edai-tag">${E(x.doc?x.doc.type:'')}</span><b>${E(x.doc?x.doc.name:'')}</b>${x.doc&&x.doc.version?' · '+E(x.doc.version):''} · page ${x.chunk.page}<div style="margin-top:4px">${snip(x.chunk.text,q)}</div></div>`).join(''):'<div class="edai-note">No matching passage in the library.</div>'):'')+onl;b.querySelectorAll('[data-edopen]').forEach(a=>a.onclick=()=>{try{window.edclDesktop.wada.open(+a.dataset.edopen)}catch(er){alert('Cannot open: '+er.message)}})};
  b.querySelector('#edai-sg').onclick=run;b.querySelector('#edai-sq').onkeydown=e=>{if(e.key==='Enter')run()}};
const wadaCard=()=>{if(!wd())return`<div class="card"><h3>📡 Library vs WADA website</h3><div class="edai-note">${E(OSTAT)}</div></div>`;
  const rows=DOCS.map(d=>({d,st:libStatus(d)})),used=new Set(rows.flatMap(r=>r.st.ids)),
    miss=OITEMS.filter(it=>RELW.test((it.title||'')+' '+(it.url||''))&&!used.has(it.id)&&(it.category!=='news')).slice(0,15);
  const badge=st=>({newer:'<b style="color:#b45309">🆕',changed:'<b style="color:#b45309">⚠',current:'<span style="color:#0a6b45">✔',nomatch:'<span style="color:#5d6f68">?',unknown:'<span style="color:#5d6f68">…'}[st.state]||'')+' '+E(st.msg)+(st.state==='newer'||st.state==='changed'?'</b>':'</span>');
  const act=it=>it?`<a data-edopen="${E(it.id)}" style="cursor:pointer">Open on WADA ↗</a>${isFile(it)?` · <a data-eddl="${E(it.id)}" style="cursor:pointer">Download file</a>`:''}`:'';
  return`<div class="card"><h3><span>📡 Library vs WADA website</span><button class="btn s sm" id="edai-chk">↻ Check WADA now</button></h3><div class="edai-note">${E(OSTAT)}. Only official wada-ama.org pages read by the EDCL WADA Updates monitor are used; no laboratory data is sent.</div>
  ${rows.length?`<div style="overflow:auto"><table class="tbl" style="width:100%"><thead><tr><th>Library document</th><th>Version</th><th>Status on WADA</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${E(r.d.name)}</td><td>${E(r.d.version||'')}</td><td>${badge(r.st)}</td><td>${act(r.st.item)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="edai-note">No documents in the library yet.</div>'}
  ${miss.length?`<h3 style="margin:14px 0 4px">WADA documents on the website that are not in your library (${miss.length})</h3><div style="overflow:auto"><table class="tbl" style="width:100%"><thead><tr><th>Title</th><th>Published</th><th>First seen</th><th></th></tr></thead><tbody>${miss.map(it=>`<tr><td>${E(it.title)}</td><td>${E(it.published||'')}</td><td>${E(String(it.first_seen||'').slice(0,10))}</td><td>${act(it)}</td></tr>`).join('')}</tbody></table></div><div class="edai-note">"Download file" saves the official file on this PC (EDCL data folder, "WADA Documents"). Then choose it with "Add to library" above.</div>`:''}</div>`};
const libTab=(b,S)=>{
  b.innerHTML=`<div class="card"><h3>Add documents</h3><div class="fg"><label>Files (PDF, HTML, TXT)<input type="file" id="edai-f" multiple accept=".pdf,.html,.htm,.txt,.md"></label><label>Type<select id="edai-ty"><option>Auto</option>${TYPES.map(t=>`<option>${t}</option>`).join('')}</select></label><label>Version / date (optional)<input id="edai-ver" placeholder="e.g. v2025, effective 2026-01"></label></div><div class="bar" style="margin-top:10px"><button class="btn" id="edai-imp">⬆ Add to library</button><span class="sub" id="edai-pr" style="margin:0"></span></div><div class="edai-note">Use only official WADA documents you downloaded from wada-ama.org. Files are read on this PC; scanned (image-only) PDFs cannot be read.</div></div>
  <div class="card"><h3>Documents in the library (${DOCS.length})</h3>${DOCS.length?`<div style="overflow:auto"><table class="tbl" style="width:100%"><thead><tr><th>Name</th><th>Type</th><th>Version</th><th>Pages</th><th>Added</th><th></th></tr></thead><tbody>${DOCS.sort((a,c)=>a.name.localeCompare(c.name)).map(d=>`<tr><td>${E(d.name)}</td><td><select data-edty="${E(d.id)}">${TYPES.map(t=>`<option${t===d.type?' selected':''}>${t}</option>`).join('')}</select></td><td><input data-edvr="${E(d.id)}" value="${E(d.version||'')}" style="width:130px"></td><td>${d.pages}</td><td>${E((d.added||'').slice(0,10))}</td><td><button class="btn d" data-eddel="${E(d.id)}">🗑 Remove</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="edai-note">No documents yet.</div>'}</div>
  ${wadaCard()}<div class="card"><h3>Share the library with another PC</h3><div class="bar"><button class="btn s" id="edai-ex">⬇ Export library file</button><label class="btn s" style="cursor:pointer">⬆ Import library file<input type="file" id="edai-im" accept=".json" style="display:none"></label></div><div class="edai-note">Build the library once, export it, copy the file over the laboratory network and import it on the other PCs.</div></div>`;
  const pr=b.querySelector('#edai-pr');
  b.querySelector('#edai-imp').onclick=async()=>{const fs=[...b.querySelector('#edai-f').files];if(!fs.length)return alert('Choose one or more files first.');const o={type:b.querySelector('#edai-ty').value,version:b.querySelector('#edai-ver').value.trim()},res=[];
    for(let i=0;i<fs.length;i++){pr.textContent=`(${i+1}/${fs.length}) ${fs[i].name} …`;try{const r=await importFile(fs[i],o,(p,n)=>{pr.textContent=`(${i+1}/${fs.length}) ${fs[i].name}: page ${p}/${n}`});await reload();res.push(fs[i].name+': '+(r.skipped?'skipped - '+r.skipped:'added ('+r.passages+' passages)'))}catch(e){res.push(fs[i].name+': FAILED - '+e.message)}}
    alert(res.join('\n'));render()};
  b.onchange=async e=>{const t=e.target;if(t.dataset.edty||t.dataset.edvr){const id=t.dataset.edty||t.dataset.edvr,d=DOCS.find(x=>x.id===id);if(!d)return;if(t.dataset.edty)d.type=t.value;else d.version=t.value.trim();await tx('docs','readwrite',s=>{s.put(d)});audit('Edit','Library: '+d.name,'type/version changed');await reload()}};
  b.onclick=async e=>{const x=e.target.closest('[data-eddel]');if(x){const d=DOCS.find(y=>y.id===x.dataset.eddel);if(d&&confirm('Remove "'+d.name+'" from the AI library?\n(The original file is not touched.)')){await delDoc(d.id);audit('Delete','Library: '+d.name,'removed');await reload();render()}}};
  b.querySelectorAll('[data-edopen]').forEach(a=>a.onclick=()=>{try{window.edclDesktop.wada.open(+a.dataset.edopen)}catch(er){alert('Cannot open: '+er.message)}});
  b.querySelectorAll('[data-eddl]').forEach(a=>a.onclick=async()=>{const it=OITEMS.find(x=>String(x.id)===a.dataset.eddl);if(!it)return;try{const r=await window.edclDesktop.wada.download({url:it.url,filename:decodeURIComponent((it.url.split('/').pop()||'wada-document').split('?')[0]),itemId:it.id});audit('Add','WADA download',it.title);alert('Saved on this PC:\n'+r.path+'\n\nNow use "Add to library" and choose this file.')}catch(er){alert('Download failed: '+er.message)}});
  const ck=b.querySelector('#edai-chk');if(ck)ck.onclick=async()=>{ck.disabled=true;ck.textContent='Checking…';try{await window.edclDesktop.wada.check()}catch(er){}await refreshOnline();render()};
  b.querySelector('#edai-ex').onclick=async()=>{const pack={format:'edcl-ai-library',version:1,exported:new Date().toISOString(),docs:await getAll('docs'),chunks:await getAll('chunks')},a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(pack)],{type:'application/json'}));a.download='EDCL-AI-library-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},2000);audit('Export','Library',DOCS.length+' documents')};
  b.querySelector('#edai-im').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const p=JSON.parse(await f.text());if(p.format!=='edcl-ai-library'||!Array.isArray(p.docs)||!Array.isArray(p.chunks))throw new Error('this is not an EDCL AI library file');
    const have=new Set(DOCS.map(d=>d.hash)),nd=p.docs.filter(d=>d&&d.id&&!have.has(d.hash)),ids=new Set(nd.map(d=>d.id)),nc=p.chunks.filter(c=>ids.has(c.docId));
    await tx(['docs','chunks'],'readwrite',([ds,cs])=>{nd.forEach(d=>ds.put(d));nc.forEach(c=>cs.put(c))});await reload();audit('Import','Library',nd.length+' documents');alert(nd.length+' document(s) added, '+(p.docs.length-nd.length)+' already present.');render()}catch(er){alert('Import failed: '+er.message)}};};
/* ---- Settings ---- */
const EVAL_TEXT={dpa:"The provider's API terms / data-processing agreement were reviewed: our data is not used to train models.",retention:'Provider data retention is zero or short (30 days or less) and any abuse-monitoring retention is acceptable.',residency:'The place / region where the data is processed is acceptable to the laboratory and its authorities.',classification:'I understand that ONLY public content (the question and public WADA / scientific text) can be sent; laboratory, employee and internal data never are.',keys:'Key handling is agreed: a dedicated key, a spending limit set at the provider, a named owner, rotation at least every 12 months.',limits:'Rate / spending limits are configured at the provider and a contact for incidents is named.',exit:'Exit plan agreed: how to switch cloud AI off here, how to revoke the key at the provider, and who does it.',legal:'Confidentiality duties (ISO/IEC 17025, WADA ISL and data-protection rules, national law) were considered and this use is compatible.',pilot:'A pilot on the separate test copy was completed and the privacy log was reviewed.'};
